from PIL import Image
import numpy as np
a=np.asarray(Image.open('/app/output/main_after1.png')).mean(2);m=a<100
# connected components flood fill
seen=np.zeros_like(m); comps=[]
for y,x in zip(*np.where(m)):
 if seen[y,x]:continue
 stack=[(y,x)];seen[y,x]=1;pts=[]
 while stack:
  yy,xx=stack.pop();pts.append((yy,xx))
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    ny,nx=yy+dy,xx+dx
    if 0<=ny<m.shape[0] and 0<=nx<m.shape[1] and m[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;stack.append((ny,nx))
 comps.append(pts)
for pts in sorted(comps,key=len,reverse=True)[:8]:
 yy=np.array([p[0] for p in pts]);xx=np.array([p[1] for p in pts]);print('n',len(pts),'bbox',xx.min(),xx.max(),yy.min(),yy.max(),'cent',xx.mean(),yy.mean())
